"""Reconnaissance over Claude Code session transcripts for the openvela project."""
import json
from pathlib import Path
from datetime import datetime, timezone

HOME = Path.home()
CANDS = [
    HOME / ".claude" / "projects" / "E--openvela",
    HOME / ".claude" / "projects" / "--wsl-localhost-Ubuntu-22-04-home-dev",
]


def load(path: Path):
    out = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            out.append(json.loads(line))
        except json.JSONDecodeError:
            pass
    return out


def first_user_text(events):
    for e in events:
        if e.get("type") != "user":
            continue
        msg = e.get("message") or {}
        c = msg.get("content")
        if isinstance(c, str):
            t = c
        elif isinstance(c, list):
            t = " ".join(b.get("text", "") for b in c
                         if isinstance(b, dict) and b.get("type") == "text")
        else:
            t = ""
        t = " ".join(t.split())
        if not t or t.startswith("<") or "system-reminder" in t[:200]:
            continue
        return t
    return "(no plain user text)"


for d in CANDS:
    if not d.is_dir():
        continue
    for f in sorted(d.glob("*.jsonl")):
        ev = load(f)
        ts = [e.get("timestamp") for e in ev if e.get("timestamp")]
        usr = [e for e in ev if e.get("type") == "user"]
        asst = [e for e in ev if e.get("type") == "assistant"]
        cwd = next((e.get("cwd") for e in ev if e.get("cwd")), "?")
        model = next((e.get("message", {}).get("model") for e in ev
                      if e.get("type") == "assistant"), "?")
        print("=" * 100)
        print(f"FILE     : {f.parent.name}/{f.name}")
        print(f"BYTES    : {f.stat().st_size:,}   RAW_LINES: {len(ev)}")
        print(f"RANGE    : {ts[0] if ts else '?'}  ->  {ts[-1] if ts else '?'}")
        print(f"MSGS     : user={len(usr)} assistant={len(asst)}")
        print(f"CWD      : {cwd}")
        print(f"MODEL    : {model}")
        print(f"FIRST_USR: {first_user_text(ev)[:400]}")

"""Scan transcripts for project milestones and confirm the WSL session belongs to openvela."""
import json
import re
from pathlib import Path

HOME = Path.home()
DIRS = [HOME / ".claude" / "projects" / "E--openvela",
        HOME / ".claude" / "projects" / "--wsl-localhost-Ubuntu-22-04-home-dev"]

PATTERNS = {
    "repo_sync": re.compile(r"repo sync", re.I),
    "tflite": re.compile(r"tflite|tensorflow|\bTFLM\b|micro_interpreter|person_detect", re.I),
    "espeak_tts": re.compile(r"espeak|pico2wave|tts", re.I),
    "build_ok": re.compile(r"build (succeeded|complete)|Build complete|编译成功|构建成功", re.I),
    "qemu": re.compile(r"qemu", re.I),
    "ai_glasses": re.compile(r"ai_glasses", re.I),
}


def load(p: Path):
    out = []
    for line in p.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            out.append(json.loads(line))
        except json.JSONDecodeError:
            pass
    return out


def all_text(e):
    msg = e.get("message") or {}
    c = msg.get("content")
    parts = []
    if isinstance(c, str):
        parts.append(c)
    elif isinstance(c, list):
        for b in c:
            if not isinstance(b, dict):
                continue
            for k in ("text", "thinking"):
                if b.get(k):
                    parts.append(str(b[k]))
            if b.get("input") is not None:
                parts.append(json.dumps(b["input"], ensure_ascii=False)[:4000])
            if b.get("content") is not None and b.get("type") == "tool_result":
                parts.append(json.dumps(b["content"], ensure_ascii=False)[:4000])
    return "\n".join(parts)


for d in DIRS:
    if not d.is_dir():
        continue
    for f in sorted(d.glob("*.jsonl")):
        ev = load(f)
        counts = {k: 0 for k in PATTERNS}
        first_hit = {}
        for e in ev:
            t = all_text(e)
            for k, rx in PATTERNS.items():
                if rx.search(t):
                    counts[k] += 1
                    first_hit.setdefault(k, e.get("timestamp", "?"))
        print("=" * 90)
        print(f"{d.name}/{f.name}")
        for k in PATTERNS:
            if counts[k]:
                print(f"   {k:<12} hits={counts[k]:<5} first={first_hit[k]}")

"""Check whether the other two Claude project dirs contain openvela-related sessions."""
import json
from pathlib import Path

HOME = Path.home()
for name in ("C--Users-10516", "e---claude"):
    d = HOME / ".claude" / "projects" / name
    if not d.is_dir():
        print(f"{name}: (no dir)")
        continue
    for f in sorted(d.rglob("*.jsonl")):
        text = f.read_text(encoding="utf-8", errors="replace")
        lower = text.lower()
        marks = {k: lower.count(k) for k in
                 ("openvela", "ai_glasses", "nuttx", "tflite", "repo sync", "qemu")
                 if lower.count(k)}
        ts = []
        cwd = "?"
        for line in text.splitlines()[:400]:
            line = line.strip()
            if not line:
                continue
            try:
                e = json.loads(line)
            except json.JSONDecodeError:
                continue
            if e.get("timestamp"):
                ts.append(e["timestamp"])
            if e.get("cwd"):
                cwd = e["cwd"]
        print(f"{name}/{f.name}: bytes={f.stat().st_size:,} cwd={cwd} "
              f"range={ts[0] if ts else '?'}..{ts[-1] if ts else '?'} marks={marks}")

